// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import "./IArbitrator.sol";

/**
 * @title IArbitrableProxy
 * Interface matching public/external signatures implemented in ArbiterProxy
 */
interface IArbitrableProxy {
    // ============ Enums ============
    enum DisputeType {
        Talent,
        Gig
    }

    enum DisputeStatus {
        WaitingForFreelancerFee,
        WaitingForClientFee,
        DisputeCreated,
        Resolved
    }

    // ============ Basic getters ============
    function arbitrator() external view returns (IArbitrator);

    function disputeCount() external view returns (uint256);

    // ============ Creation / fee payment / lifecycle ============
    function createDispute(
        uint256 _externalId1,
        uint256 _externalId2,
        DisputeType _disputeType,
        bytes calldata _arbitratorExtraData,
        address _freelancer,
        address _client
    ) external returns (uint256 localDisputeId);

    function startAndPayTalentDisputeByFreelancer(
        uint256 _talentId,
        uint256 _hiredTalentId,
        address _freelancer,
        address _client,
        bytes calldata _arbitratorExtraData
    ) external payable returns (uint256 localDisputeId);

    function startAndPayTalentDisputeByClient(
        uint256 _talentId,
        uint256 _hiredTalentId,
        address _freelancer,
        address _client,
        bytes calldata _arbitratorExtraData
    ) external payable returns (uint256 localDisputeId);

    function createAndPayGigDisputeByFreelancer(
        uint256 _gigId,
        address _freelancer,
        address _client,
        bytes calldata _arbitratorExtraData
    ) external payable returns (uint256 localDisputeId);

    function createAndPayGigDisputeByClient(
        uint256 _gigId,
        address _freelancer,
        address _client,
        bytes calldata _arbitratorExtraData
    ) external payable returns (uint256 localDisputeId);

    function payArbitrationFeeByFreelancer(
        address _caller,
        uint256 _localDisputeId,
        bytes calldata _arbitratorExtraData
    ) external payable;

    function payArbitrationFeeByClient(
        address _caller,
        uint256 _localDisputeId,
        bytes calldata _arbitratorExtraData
    ) external payable;

    function getDisputeStatus(uint256 _localDisputeId) external view returns (DisputeStatus);

    function getCurrentRuling(uint256 _localDisputeId) external view returns (uint256);

    function hasTimedOut(uint256 _localDisputeId) external view returns (bool);

    function timeoutByInaction(uint256 _localDisputeId) external;

    function finalizeDispute(uint256 _localDisputeId) external;

    // ============ Appeal interactions ============

    function fundAppeal(address _caller, uint256 _localDisputeId, uint8 _side) external payable;

    // ============ Events ============
    event TalentDisputeCreated(
        uint256 indexed localDisputeId,
        uint256 indexed talentId,
        uint256 indexed hiredTalentId,
        address freelancer,
        address client,
        uint256 feeDepositDeadline
    );

    event FreelancerPayedTalentArbitrationFee(
        uint256 indexed localDisputeId,
        uint256 indexed talentId,
        uint256 indexed hiredTalentId,
        address freelancer,
        uint256 amountPaid,
        uint256 totalAmountPaid
    );

    event ClientPayedTalentArbitrationFee(
        uint256 indexed localDisputeId,
        uint256 indexed talentId,
        uint256 indexed hiredTalentId,
        address client,
        uint256 amountPaid,
        uint256 totalAmountPaid
    );

    event TalentDisputeRaised(
        uint256 indexed localDisputeId,
        uint256 indexed klerosDisputeId,
        uint256 indexed talentId,
        uint256 hiredTalentId
    );

    event GigDisputeCreated(
        uint256 indexed localDisputeId,
        uint256 indexed gigId,
        address freelancer,
        address client,
        uint256 feeDepositDeadline
    );

    event FreelancerPayedGigArbitrationFee(
        uint256 indexed localDisputeId,
        uint256 indexed gigId,
        address indexed freelancer,
        uint256 amountPaid,
        uint256 totalAmountPaid
    );

    event ClientPayedGigArbitrationFee(
        uint256 indexed localDisputeId,
        uint256 indexed gigId,
        address indexed client,
        uint256 amountPaid,
        uint256 totalAmountPaid
    );

    event GigDisputeRaised(
        uint256 indexed localDisputeId,
        uint256 indexed klerosDisputeId,
        uint256 indexed gigId
    );

    event GigDisputeTimeoutByInaction(
        uint256 indexed localDisputeId,
        uint256 indexed gigId,
        uint256 ruling,
        address winner
    );

    event TalentDisputeTimeoutByInaction(
        uint256 indexed localDisputeId,
        uint256 indexed talentId,
        uint256 indexed hiredTalentId,
        uint256 ruling,
        address winner
    );

    event GigAppealContribution(
        uint256 indexed localDisputeId,
        uint256 indexed round,
        uint256 gigId,
        uint8 side,
        address contributor,
        uint256 amount,
        uint256 totalPaid,
        uint256 requiredAmount
    );

    event TalentAppealContribution(
        uint256 indexed localDisputeId,
        uint256 indexed round,
        uint256 talentId,
        uint256 hiredTalentId,
        uint8 side,
        address contributor,
        uint256 amount,
        uint256 totalPaid,
        uint256 requiredAmount
    );

    event GigAppealCreated(
        uint256 indexed localDisputeId,
        uint256 indexed klerosDisputeId,
        uint256 indexed round,
        uint256 gigId
    );

    event TalentAppealCreated(
        uint256 indexed localDisputeId,
        uint256 indexed klerosDisputeId,
        uint256 indexed round,
        uint256 talentId,
        uint256 hiredTalentId
    );

    event GigFeesAndRewardsWithdrawn(
        uint256 indexed localDisputeId,
        uint256 gigId,
        address beneficiary,
        uint256 reward
    );

    event TalentFeesAndRewardsWithdrawn(
        uint256 indexed localDisputeId,
        uint256 talentId,
        uint256 hiredTalentId,
        address beneficiary,
        uint256 reward
    );

    event TalentRuling(
        uint256 indexed localDisputeId,
        uint256 talentId,
        uint256 hiredTalentId,
        uint256 ruling
    );

    event GigRuling(
        uint256 indexed localDisputeId,
        uint256 gigId,
        uint256 ruling
    );

    event TalentRoundTimeoutByInaction(
        uint256 indexed localDisputeId,
        uint256 indexed round,
        uint256 talentId,
        uint256 hiredTalentId,
        uint256 ruling,
        address winner
    );

    event GigRoundTimeoutByInaction(
        uint256 indexed localDisputeId,
        uint256 indexed round,
        uint256 gigId,
        uint256 ruling,
        address winner
    );

    event TalentAppealExternallyFunded(
        uint256 indexed localDisputeId,
        uint256 indexed round,
        uint256 indexed talentId,
        uint256 hiredTalentId
    );

    event GigAppealExternallyFunded(
        uint256 indexed localDisputeId,
        uint256 indexed round,
        uint256 indexed gigId
    );

}

contracts/common/IArbitrator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./IArbitrable.sol";

/**
 * @title Arbitrator
 * Arbitrator abstract contract.
 * When developing arbitrator contracts we need to:
 * - Define the functions for dispute creation (createDispute) and appeal (appeal). Don't forget to store the arbitrated contract and the disputeID (which should be unique, may nbDisputes).
 * - Define the functions for cost display (arbitrationCost and appealCost).
 * - Allow giving rulings. For this a function must call arbitrable.rule(disputeID, ruling).
 */
interface IArbitrator {
    enum DisputeStatus {
        Waiting,
        Appealable,
        Solved
    }

    /**
     * @dev To be emitted when a dispute is created.
     * @param _disputeID ID of the dispute.
     * @param _arbitrable The contract which created the dispute.
     */
    event DisputeCreation(uint256 indexed _disputeID, IArbitrable indexed _arbitrable);

    /**
     * @dev To be emitted when a dispute can be appealed.
     * @param _disputeID ID of the dispute.
     * @param _arbitrable The contract which created the dispute.
     */
    event AppealPossible(uint256 indexed _disputeID, IArbitrable indexed _arbitrable);

    /**
     * @dev To be emitted when the current ruling is appealed.
     * @param _disputeID ID of the dispute.
     * @param _arbitrable The contract which created the dispute.
     */
    event AppealDecision(uint256 indexed _disputeID, IArbitrable indexed _arbitrable);

    /**
     * @dev Create a dispute. Must be called by the arbitrable contract.
     * Must be paid at least arbitrationCost(_extraData).
     * @param _choices Amount of choices the arbitrator can make in this dispute.
     * @param _extraData Can be used to give additional info on the dispute to be created.
     * @return disputeID ID of the dispute created.
     */
    function createDispute(uint256 _choices, bytes calldata _extraData) external payable returns (uint256 disputeID);

    /**
     * @dev Compute the cost of arbitration. It is recommended not to increase it often, as it can be highly time and gas consuming for the arbitrated contracts to cope with fee augmentation.
     * @param _extraData Can be used to give additional info on the dispute to be created.
     * @return cost Amount to be paid.
     */
    function arbitrationCost(bytes calldata _extraData) external view returns (uint256 cost);

    /**
     * @dev Appeal a ruling. Note that it has to be called before the arbitrator contract calls rule.
     * @param _disputeID ID of the dispute to be appealed.
     * @param _extraData Can be used to give extra info on the appeal.
     */
    function appeal(uint256 _disputeID, bytes calldata _extraData) external payable;

    /**
     * @dev Compute the cost of appeal. It is recommended not to increase it often, as it can be highly time and gas consuming for the arbitrated contracts to cope with fee augmentation.
     * @param _disputeID ID of the dispute to be appealed.
     * @param _extraData Can be used to give additional info on the dispute to be created.
     * @return cost Amount to be paid.
     */
    function appealCost(uint256 _disputeID, bytes calldata _extraData) external view returns (uint256 cost);

    /**
     * @dev Compute the start and end of the dispute's current or next appeal period, if possible. If not known or appeal is impossible: should return (0, 0).
     * @param _disputeID ID of the dispute.
     * @return start The start of the period.
     * @return end The end of the period.
     */
    function appealPeriod(uint256 _disputeID) external view returns (uint256 start, uint256 end);

    /**
     * @dev Return the status of a dispute.
     * @param _disputeID ID of the dispute to rule.
     * @return status The status of the dispute.
     */
    function disputeStatus(uint256 _disputeID) external view returns (DisputeStatus status);

    /**
     * @dev Return the current ruling of a dispute. This is useful for parties to know if they should appeal.
     * @param _disputeID ID of the dispute.
     * @return ruling The ruling which has been given or the one which will be given if there is no appeal.
     */
    function currentRuling(uint256 _disputeID) external view returns (uint256 ruling);

    /**
     * @dev Execute the ruling of a dispute. Must be called by the arbitrable contract.
     * @param _disputeID ID of the dispute to rule.
     */
    function executeRuling(uint256 _disputeID) external;
}

